{
  "model": "gpt-5.6-sol",
  "messages": [
    {
      "role": "user",
      "content": "What is 5 plus 3?"
    }
  ],
  "tools": [
    {
      "type": "function",
      "function": {
        "name": "add",
        "description": "Adds two numbers together.",
        "parameters": {
          "type": "object",
          "properties": {
            "a": {
              "type": "number",
              "description": "First number"
            },
            "b": {
              "type": "number",
              "description": "Second number"
            }
          },
          "required": [
            "a",
            "b"
          ]
        }
      }
    }
  ]
}

{
  "model": "gpt-5.6-sol",
  "messages": [
    {
      "role": "system",
      "content": "You are an expert on Robert Jordan's The Wheel of Time book series. Answer questions using only established lore from the fourteen novels and New Spring. Structure longer answers with short headings or bullet points."
    },
    {
      "role": "user",
      "content": "Who is Gitara Moroso?"
    }
  ],
  "max_completion_tokens": 25000
}

{
  "model": "smart-router",
  "messages": [
    {
      "role": "system",
      "content": "You are a cloud architect with deep AWS expertise. Be concise and specific."
    },
    {
      "role": "user",
      "content": "Think step by step and analyze the security implications of IRSA versus static IAM credentials"
    }
  ],
  "max_tokens": 25000
}

{
  "model": "gpt-5.6-sol",
  "messages": [
    {
      "role": "user",
      "content": "Name three nations of the Wheel of Time, one per line."
    }
  ],
  "stream": true,
  "stream_options": {
    "include_usage": true
  },
  "max_tokens": 200
}

{
  "model": "claude-sonnet-4-5",
  "max_tokens": 200,
  "messages": [
    {
      "role": "user",
      "content": "In one sentence, who is Paul Atreides?"
    }
  ]
}

{
  "model": "openai/dall-e-3",
  "prompt": "A cat sitting on a Kubernetes pod",
  "n": 1,
  "size": "1024x1024"
}

{
  "model": "openrouter/google/gemini-3-pro-image-preview",
  "messages": [
    {
      "role": "user",
      "content": "A clean, flat-design diagram on a white background: one rounded rectangle labeled \"Gateway\" in the center, with three arrows pointing to boxes labeled \"Models\", \"Tools\" and \"Agents\"."
    }
  ],
  "modalities": [
    "image",
    "text"
  ],
  "extra_body": {
    "image_config": {
      "aspect_ratio": "16:9",
      "image_size": "4K"
    }
  }
}

{
  "model": "rerank-2.5",
  "query": "Who is the Dragon Reborn?",
  "documents": [
    "Rand al'Thor is the Dragon Reborn.",
    "Paul Atreides rules Arrakis.",
    "Egwene al'Vere becomes the Amyrlin Seat."
  ],
  "top_n": 2
}

{
  "model": "gpt-5.6-sol",
  "messages": [
    {
      "role": "system",
      "content": "You are a read-only Kubernetes assistant. Use the available tools and answer only from tool results."
    },
    {
      "role": "user",
      "content": "How many nodes does the cluster have and which Kubernetes version do they run?"
    }
  ],
  "tools": [
    {
      "type": "mcp",
      "server_url": "litellm_proxy/mcp/kagent_tools",
      "require_approval": "never"
    }
  ]
}

{
  "agent_name": "cluster_agent",
  "agent_card_params": {
    "protocolVersion": "1.0",
    "name": "cluster_agent",
    "description": "Read-only Kubernetes assistant that answers questions about this EKS cluster.",
    "url": "http://kagent-controller.kagent.svc.cluster.local:8083/api/a2a/kagent/cluster-agent/",
    "version": "1.0.0",
    "defaultInputModes": [
      "text"
    ],
    "defaultOutputModes": [
      "text"
    ],
    "capabilities": {
      "streaming": true
    },
    "skills": [
      {
        "description": "Answers questions about workloads, nodes, events, logs and Helm releases in the cluster.",
        "examples": [
          "How many nodes does the cluster have and what version are they running?",
          "Which pods are not Running, and why?",
          "Which Helm releases are installed?"
        ],
        "id": "cluster-questions",
        "name": "Cluster questions",
        "tags": [
          "kubernetes",
          "eks",
          "read-only"
        ]
      }
    ]
  }
}

{
  "jsonrpc": "2.0",
  "id": "1",
  "method": "message/send",
  "params": {
    "message": {
      "role": "user",
      "kind": "message",
      "messageId": "{{$guid}}",
      "parts": [
        {
          "kind": "text",
          "text": "How many nodes does this cluster have, and which Kubernetes version do they run?"
        }
      ]
    }
  }
}
